/**
 * JSS Lesson Note Templates — Part 1
 * JSS 1: English Language & Mathematics — All 3 Terms × 12 Weeks
 * Original content based on Nigerian NERDC curriculum.
 */

export interface LNTemplate {
  title: string; level: string; className: string; subjectName: string;
  term: string; weekNumber: number; topic: string; duration: string;
  objectives: string; entryBehaviour: string; instructionalMaterials: string;
  content: string; teacherActivities: string; studentActivities: string;
  evaluationQuestions: string; assignments: string; references: string;
}

function lnt(
  className: string, subjectName: string, level: string,
  term: string, weekNumber: number,
  topic: string, objectives: string, entryBehaviour: string,
  materials: string, content: string, teacherActs: string, studentActs: string,
  evalQ: string, assign: string, refs: string
): LNTemplate {
  return {
    title: `${className} ${subjectName} – ${topic}`,
    level, className, subjectName, term, weekNumber, topic,
    duration: "40 minutes",
    objectives, entryBehaviour, instructionalMaterials: materials,
    content, teacherActivities: teacherActs, studentActivities: studentActs,
    evaluationQuestions: evalQ, assignments: assign, references: refs,
  };
}

